mapper.select:
SELECT a.id, a.title, a.description, a.class_id, a.unit_id, a.created_by, a.deadline, a.created_time, c.name as class_name, u.name as unit_name, creator.real_name as creator_name, creator.nickname as creator_nickname FROM assignments a LEFT JOIN classes c ON a.class_id = c.id LEFT JOIN units u ON a.unit_id = u.id LEFT JOIN users creator ON a.created_by = creator.id WHERE 1=1
AND a.created_by = #{teacherId}
AND a.class_id = #{classId}
AND (a.title LIKE CONCAT('%', #{keyword}, '%') OR a.description LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY a.created_time DESC
